ee:message.ee:set-payload:
%dw 2.0
output application/xml

var subdomain = Mule::p('secure::soap.subdomain')
var AccessToken = vars.token
---
"s:Envelope" @(
  "xmlns:s": "http://www.w3.org/2003/05/soap-envelope",
  "xmlns:a": "http://schemas.xmlsoap.org/ws/2004/08/addressing",
  "xmlns:u": "http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd"
): {
  "s:Header": {
    "a:Action" @("s:mustUnderstand": "1"): "Retrieve",
    "a:To" @("s:mustUnderstand": "1"): "https://" ++ subdomain ++ "/Service.asmx",
    fueloauth @("xmlns": "http://exacttarget.com"): AccessToken
  },
  "s:Body" @(
    "xmlns:xsi": "http://www.w3.org/2001/XMLSchema-instance",
    "xmlns:xsd": "http://www.w3.org/2001/XMLSchema"
  ): {
    RetrieveRequestMsg @("xmlns": "http://exacttarget.com/wsdl/partnerAPI"): {
      RetrieveRequest: {
        ObjectType: "DataExtensionObject[Alertes_Notifications]",
        Properties: [
          "ContactId",
          "Message_Popup",
          "Message1_Mobile",
          "Message2_Mobile",
          "Message3_Mobile",
          "Title_Mobile",
          "TitleCTA_Mobile",
          "UrlCTA_Mobile",
          "LimitDate_Mobile",
          "PublicationDate_Mobile",
          "Message1_Web",
          "Message2_Web",
          "Message3_Web",
          "UrlCTA_Web",
          "TitleCTA_Web",
          "LimitDate_Web",
          "Title_Web",
          "PublishedDate_Web",
          "Type",
          "order"
        ],
        Filter @("xsi:type": "SimpleFilterPart"): {
          Property: "ContactId",
          SimpleOperator: "equals",
          Value: vars.filterVal
        }
      }
    }
  }
}

